package com.bank.collect;

import java.math.BigDecimal;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class TransactionCollectorDemo {
    private static final Logger log = Logger.getLogger(TransactionCollectorDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000.00"));
        TransactionCollectorService svc = new TransactionCollectorService();

        // DYNAMIC size unknown up front → ArrayList grows automatically.
        List<BigDecimal> amounts = svc.collect(rajesh);
        amounts.add(new BigDecimal("8000.00"));   // more arrive during the day
        log.info(() -> "collected amounts (size()=" + amounts.size() + ") = " + amounts);

        // FIXED, dense primitive data → primitive long[] (no boxing).
        long[] hourly = svc.hourlyCounts();
        log.info(() -> "hourly counts (length=" + hourly.length + ") = "
                + java.util.Arrays.toString(hourly));

        // length vs size(): array uses length field, list uses size() method.
        log.fine(() -> "array.length=" + hourly.length + ", list.size()=" + amounts.size());

        // Convert list -> array when an array API is required.
        BigDecimal[] asArray = svc.toArray(amounts);
        log.info(() -> "converted to array length = " + asArray.length);

        // Arrays are covariant: wrong element type throws at RUNTIME.
        try {
            Object[] objs = new String[2];   // covariance allows this
            objs[0] = Integer.valueOf(1);    // ArrayStoreException at runtime
        } catch (ArrayStoreException e) {
            log.warning("ArrayStoreException: array covariance hole (ArrayList would catch at compile time)");
        }
    }
}

