class TransactionCollectorService {
    private static final Logger log = Logger.getLogger(TransactionCollectorService.class.getName());

    // Growable, generic, type-safe collection for an unknown number of amounts.
    List<BigDecimal> collect(Account account) {
        List<BigDecimal> list = new java.util.ArrayList<>();
        list.add(new BigDecimal("45000.00"));
        list.add(new BigDecimal("12000.00"));
        list.add(new BigDecimal("30000.00"));
        log.fine(() -> "Collected initial amounts for " + account.getAccountId());
        return list;   // caller may keep adding
    }

    // Fixed, dense primitive array: 24 hours, no boxing, compact.
    long[] hourlyCounts() {
        long[] counts = new long[24];
        counts[9] = 5; counts[12] = 8; counts[18] = 3;   // peak hours
        return counts;
    }

    // Convert a List to an array (sized by the collection).
    BigDecimal[] toArray(List<BigDecimal> list) {
        return list.toArray(new BigDecimal[0]);
    }
}

// ─── Would be in util/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
